657: void check_tet_conn(mshType& mesh)
658: {
659:   //std::cout << "[check_tet_conn] ========== check_tet_conn ========== " << std::endl;
660:   Vector<double> v1, v2, v3;
661:   int num_elems = mesh.gnEl;
662:   int num_reorder = 0;
663:   //std::cout << "[check_tet_conn] mesh.gIEN.data(): " << mesh.gIEN.data() << std::endl;
664:   //std::cout << "[check_tet_conn] mesh.x.data(): " << mesh.x.data() << std::endl;
665: 
666:   for (int e = 0; e < num_elems; e++) {
667:     //std::cout << "[check_tet_conn] -------- e " << e << std::endl;
668:     int a = 0, b = 0;
669:     bool qFlag = false;
670:     auto elem_conn = mesh.gIEN.col(e);
671:     auto xl = mesh.x.cols(elem_conn);
672: 
673:     v1 = xl[1] - xl[0];
674:     v2 = xl[2] - xl[1];
675:     v3 = xl[3] - xl[2];
676:     auto v4 = v1.cross(v2);
677:     int sn = utils::sign(v3.dot(v4));
678: 
679:     if (sn == 1) {
680:       a = 0;
681:       b = 1;
682:       qFlag = true;
683:       num_reorder += 1;
684:       if (e == 0) {
685:         //std::cout << "[check_tet_conn] Reorder element connectivity for element " << e << std::endl;
686:       }
687:       //std::cout << "[check_tet_conn] Reorder element connectivity for element " << e << std::endl;
688:     } else if (sn == 0) { 
689:       throw std::runtime_error("Tet element " + std::to_string(e) + " is distorted.");
690:     } 
691: 
692:     utils::swap( mesh.gIEN(a,e), mesh.gIEN(b,e));
693: 
694:     if (qFlag) {
695:       if (mesh.eType == consts::ElementType::TET10) {
696:         a = 5; b = 6;
697:         utils::swap(mesh.gIEN(a,e), mesh.gIEN(b,e));
698:         a = 7; b = 8;
699:         utils::swap(mesh.gIEN(a,e), mesh.gIEN(b,e));
700:       }
701:     }
702:   }
703: 
704:   //std::cout << "[check_tet_conn] Reorder " << num_reorder << " element connectivity from " << num_elems << "  elements." << std::endl;

