453: void calc_nbc(mshType& mesh, faceType& face)
454: {
455:   #define n_debug_calc_nbc 
456:   #ifdef debug_calc_nbc 
457:   DebugMsg dmsg(__func__, 0);
458:   dmsg.banner();
459:   dmsg << "Face: " << face.name;
460:   #endif
461:   int num_elems = mesh.gnEl;
462:   int num_nodes = mesh.gnNo;
463:   auto incNd = Vector<int>(mesh.gnNo);
464:   face.nNo = 0;
465: 
466:   // Check face nodes.
467:   //
468:   std::string msg("[calc_nbc] ");
469: 
470:   for (int e = 0; e < face.nEl; e++ ) {
471:     //dmsg << "---- e " << std::to_string(e+1) + " -----";
472:     int Ec = face.gE(e);
473:     //dmsg << "Ec: " << Ec;
474: 
475:     if (Ec > num_elems) {
476:       throw std::runtime_error(msg + "element ID " + std::to_string(Ec) + " exceeds the number of elements (" + std::to_string(num_elems) +
477:           ") in the mesh.");
478:     } else if (Ec < 0) {
479:       throw std::runtime_error(msg + "element ID " + std::to_string(Ec) + " is < 0.");
480:     }
481: 
482:     for (int a = 0; a < face.eNoN; a++) {
483:       int Ac = face.IEN(a,e);
484:       //dmsg << "Ac: " << Ac;
485:       if (Ac > num_nodes) { 
486:         throw std::runtime_error(msg + "element " + std::to_string(e) + " has a node " + std::to_string(Ac) + " that exceeds the number of nodes (" + 
487:             std::to_string(num_nodes) + ") in the mesh.");
488:       }
489:       if (Ac < 0) {
490:         throw std::runtime_error(msg + "element " + std::to_string(e) + " has a node " + std::to_string(Ac) + " that is < 0.");
491:       }
492:       auto elem_conn = mesh.gIEN.col(Ec);
493:       if (std::find(elem_conn.begin(), elem_conn.end(), Ac) == elem_conn.end()) {
494:         throw std::runtime_error(msg + "element " + std::to_string(e) + " has a node " + std::to_string(Ac) + 
495:             " that does not belong to its parent element " + std::to_string(Ec) + ".");
496:       }
497: 
498:       if (incNd(Ac) == 0) {
499:         face.nNo += 1;
500:         incNd(Ac) = 1;
501:       }
502:     }
503:   }
504: 
505:   // Set face nodes.
506:   face.gN = Vector<int>(face.nNo);
507:   int a = 0;
508:   for (int Ac = 0; Ac < mesh.gnNo; Ac++) {
509:     if (incNd(Ac) != 0) {
510:       face.gN[a] = Ac;
511:       a = a + 1;
512:     } 
513:   } 
514: }
