156: /// Permutation from a solver element's local node ordering to the FE Basis
157: /// ReferenceNodeLayout ordering, indexed by the solver-local node number:
158: /// map[solver_node] is the matching FE Basis node. The solver and the FE Basis
159: /// library number element nodes with different conventions, so this table
160: /// reconciles them at the adapter boundary. An empty span means the two
161: /// orderings already coincide (identity) and no permutation is applied, which
162: /// holds for the line, Quad4/8/9, and the entire hex family (Hex8/20/27): the FE
163: /// Basis exposes those in the same VTK-based ordering the solver ingests from
164: /// .vtu meshes. Only the simplex families need a permutation, because the solver
165: /// labels simplex corners origin-last while the FE Basis lattice is origin-first;
166: /// Wedge6 (WDG) reuses the Triangle6 table, since its two triangular node triples
167: /// are reordered exactly like a 6-node triangle.
168: /// \note These tables must stay consistent with the FE Basis lattice ordering;
169: /// a mismatch would silently assign shape functions to the wrong nodes.
170: std::span<const std::size_t> solver_to_basis_node_map(consts::ElementType eType)
171: {
172:   static constexpr std::array<std::size_t, 3> tri3{1, 2, 0};
173:   static constexpr std::array<std::size_t, 6> tri6{1, 2, 0, 4, 5, 3};
174:   static constexpr std::array<std::size_t, 4> tet4{1, 2, 3, 0};
175:   static constexpr std::array<std::size_t, 10> tet10{1, 2, 3, 0, 5, 9, 8, 4, 6, 7};
176: 
177:   switch (eType) {
178:     case consts::ElementType::TRI3:
179:       return tri3;
180:     case consts::ElementType::TRI6:
181:     case consts::ElementType::WDG:
182:       return tri6;
183:     case consts::ElementType::TET4:
184:       return tet4;
185:     case consts::ElementType::TET10:
186:       return tet10;
187:     default:
188:       return {};
189:   }
190: }
191: 
192: /// Map a single solver-local node index to its FE Basis node index for eType by
193: /// applying solver_to_basis_node_map (identity when no permutation is
194: /// registered). Throws BasisNodeOrderingException when solver_node is negative
195: /// or falls outside the element's node map.
196: std::size_t basis_index_for_solver_node(consts::ElementType eType, const int solver_node)
197: {
198:   if (solver_node < 0) {
199:     svmp::raise<febasis::BasisNodeOrderingException>("Solver node " + std::to_string(solver_node) +
200:             " is outside node map for " + solver_element_name(eType));
201:   }
