547:     dmsg << "---------- e: " << e+1;
548:     #endif
549:     cDmn = all_fun::domain(com_mod, lM, cEq, e);
550:     auto cPhys = eq.dmn[cDmn].phys;
551: 
552:     if (cPhys != EquationType::phys_fluid) {
553:       continue;
554:     }
555:     
556:     double brinkman_inverse_permeability = eq.dmn[cDmn].prop.at(PhysicalPropertyType::brinkman_inverse_permeability);
557: 
558:     //  Update shape functions for NURBS
559:     if (lM.eType == ElementType::NRB) {
560:       //CALL NRBNNX(lM, e)
561:     }
562: 
563:     // Create local copies
564:     for (int a = 0; a < eNoN; a++) {
565:       int Ac = lM.IEN(a,e);
566:       ptr(a) = Ac;
567: 
568:       for (int i = 0; i < xl.nrows(); i++) {
569:         xl(i,a) = com_mod.x(i,Ac);
570:         bfl(i,a) = com_mod.Bf(i,Ac);
571:      }
572:       for (int i = 0; i < al.nrows(); i++) {
573:         al(i,a) = Ag(i,Ac);
574:         yl(i,a) = Yg(i,Ac);
575:       }
576:     }
577: 
578:     // Initialize residual and tangents
579:     lR = 0.0;
580:     lK = 0.0;
581:     std::array<fsType,2> fs;
582: 
583:     // Set function spaces for velocity and pressure.
584:     fs::get_thood_fs(com_mod, fs, lM, vmsStab, 1);
585: 
586:     // Define element coordinates appropriate for function spaces
587:     Array<double> xwl(nsd,fs[0].eNoN); 
588:     Array<double> Nwx(nsd,fs[0].eNoN); 
589:     Array<double> Nwxx(l,fs[0].eNoN);
590: 
591:     Array<double> xql(nsd,fs[1].eNoN); 
592:     Array<double> Nqx(nsd,fs[1].eNoN);
593: 
594:     #ifdef debug_construct_fluid
595:     dmsg;
596:     dmsg << "l: " << l;
597:     dmsg << "fs[0].eNoN: " << fs[0].eNoN;
598:     dmsg << "fs[1].eNoN: " << fs[1].eNoN;
599:     #endif
600: 
601:     xwl = xl;
602: 
603:     for (int i = 0; i < xql.nrows(); i++) { 
604:       for (int j = 0; j < fs[1].eNoN; j++) { 
605:         xql(i,j) = xl(i,j);
606:       }
607:     }
608: 
609:     // Gauss integration 1
610:     //
611:     #ifdef debug_construct_fluid
612:     dmsg;
613:     dmsg << "Gauss integration 1 ... " << "";
614:     dmsg << "fs[1].nG: " << fs[0].nG;
615:     dmsg << "fs[1].lShpF: " << fs[0].lShpF;
616:     dmsg << "fs[2].nG: " << fs[1].nG;
617:     dmsg << "fs[2].lShpF: " << fs[1].lShpF;
618:     #endif
619: 
620:     double Jac{0.0};
621:     Array<double> ksix(nsd,nsd);
622:     // Total resistance factor value of the RIS valves for the current element 
623:     // at different quadrature points
624:     Vector<double> urisFactorTotalEl;
625:     Array<double> urisValveVelTermTotalEl;
626:     if (com_mod.urisFlag) {
627:       uris::eval_uris_ris_factors_quadrature(com_mod, lM, fs[0], e, urisFactorTotalEl, urisValveVelTermTotalEl);
628:     }
629: 
630:     for (int g = 0; g < fs[0].nG; g++) {
631:       #ifdef debug_construct_fluid
632:       dmsg << "===== g: " << g+1;
633:       #endif
634:       if (g == 0 || !fs[1].lShpF) {
635:         auto Nx = fs[1].Nx.rslice(g);
636:         nn::gnn(fs[1].eNoN, nsd, nsd, Nx, xql, Nqx, Jac, ksix);
637:         if (utils::is_zero(Jac)) {
638:            throw std::runtime_error("[construct_fluid] Jacobian for element " + std::to_string(e) + " is < 0.");
639:         }
640:       }
641: 
642:       if (g == 0 || !fs[0].lShpF) {
643:         auto Nx = fs[0].Nx.rslice(g);
644:         nn::gnn(fs[0].eNoN, nsd, nsd, Nx, xwl, Nwx, Jac, ksix);
645:         if (utils::is_zero(Jac)) {
646:            throw std::runtime_error("[construct_fluid] Jacobian for element " + std::to_string(e) + " is < 0.");
647:         }
648: 
649:         auto Nxx = fs[0].Nxx.rslice(g);
650:         nn::gn_nxx(l, fs[0].eNoN, nsd, nsd, Nx, Nxx, xwl, Nwx, Nwxx); 
651:       }
652: 
653:       double w = fs[0].w(g) * Jac;
654:       #ifdef debug_construct_fluid
655:       dmsg << "Jac: " << Jac;
656:       dmsg << "w: " << w;
657:       #endif
658: 
659:       // Compute momentum residual and tangent matrix.
660:       //
661:       if (nsd == 3) {
662:         auto N0 = fs[0].N.rcol(g); 
663:         auto N1 = fs[1].N.rcol(g); 
664:         double urisFactorTotal = 0.0;
665:         Vector<double> urisValveVelTermTotal(nsd);
666:         if (com_mod.urisFlag) {
667:           urisFactorTotal = urisFactorTotalEl(g);
668:           urisValveVelTermTotal = urisValveVelTermTotalEl.rcol(g);
669:         }
670:         fluid_3d_m(com_mod, vmsStab, fs[0].eNoN, fs[1].eNoN, w, ksix, N0, N1, 
671:             Nwx, Nqx, Nwxx, al, yl, bfl, lR, lK, brinkman_inverse_permeability,
672:             urisFactorTotal, urisValveVelTermTotal);
673: 
674:       } else if (nsd == 2) {
675:         auto N0 = fs[0].N.rcol(g); 
676:         auto N1 = fs[1].N.rcol(g); 
677:         fluid_2d_m(com_mod, vmsStab, fs[0].eNoN, fs[1].eNoN, w, ksix, N0, N1, 
678:             Nwx, Nqx, Nwxx, al, yl, bfl, lR, lK, brinkman_inverse_permeability);
679:       }
680:     } // g: loop
681: 
682:     // Set function spaces for velocity and pressure.
683:     //
684:     fs::get_thood_fs(com_mod, fs, lM, vmsStab, 2);
685: 
686:     // Gauss integration 2
687:     //
688:     #ifdef debug_construct_fluid
689:     dmsg;
690:     dmsg << "Gauss integration 2 ... " << "";
691:     dmsg << "fs[1].nG: " << fs[0].nG;
692:     dmsg << "fs[1].lShpF: " << fs[0].lShpF;
693:     dmsg << "fs[2].nG: " << fs[1].nG;
694:     dmsg << "fs[2].lShpF: " << fs[1].lShpF;
695:     #endif
696: 
697:     // If the number of quadrature points is different for the continuity and 
698:     // momentum function spaces, recompute the RIS factor
699:     if (com_mod.urisFlag) {
700:       if (urisFactorTotalEl.size() != fs[1].nG) {
701:         uris::eval_uris_ris_factors_quadrature(com_mod, lM, fs[1], e, urisFactorTotalEl, urisValveVelTermTotalEl);
702:       }
703:     }
704: 
705:     for (int g = 0; g < fs[1].nG; g++) {
706:       if (g == 0 || !fs[0].lShpF) {
707:         auto Nx = fs[0].Nx.rslice(g);
708:         nn::gnn(fs[0].eNoN, nsd, nsd, Nx, xwl, Nwx, Jac, ksix);
709: 
710:         if (utils::is_zero(Jac)) {
711:            throw std::runtime_error("[construct_fluid] Jacobian for element " + std::to_string(e) + " is < 0.");
712:         }
713:       }
714: 
715:       if (g == 0 || !fs[1].lShpF) {
716:         auto Nx = fs[1].Nx.rslice(g);
717:         nn::gnn(fs[1].eNoN, nsd, nsd, Nx, xql, Nqx, Jac, ksix);
718: 
719:         if (utils::is_zero(Jac)) {
720:            throw std::runtime_error("[construct_fluid] Jacobian for element " + std::to_string(e) + " is < 0.");
721:         }
722:       }
723:       double w = fs[1].w(g) * Jac;
724: 
725:       // Compute continuity residual and tangent matrix.
726:       //
727:       if (nsd == 3) {
728:         auto N0 = fs[0].N.rcol(g); 
729:         auto N1 = fs[1].N.rcol(g); 
730:         double urisFactorTotal = 0.0;
731:         Vector<double> urisValveVelTermTotal(nsd);
732:         if (com_mod.urisFlag) {
733:           urisFactorTotal = urisFactorTotalEl(g);
734:           urisValveVelTermTotal = urisValveVelTermTotalEl.rcol(g);
735:         }
736:         fluid_3d_c(com_mod, vmsStab, fs[0].eNoN, fs[1].eNoN, w, ksix, N0, N1, 
737:               Nwx, Nqx, Nwxx, al, yl, bfl, lR, lK, brinkman_inverse_permeability,
738:               urisFactorTotal, urisValveVelTermTotal);
739: 
740:       } else if (nsd == 2) {
741:         auto N0 = fs[0].N.rcol(g); 
742:         auto N1 = fs[1].N.rcol(g); 
743:         fluid_2d_c(com_mod, vmsStab, fs[0].eNoN, fs[1].eNoN, w, ksix, N0, N1, 
744:               Nwx, Nqx, Nwxx, al, yl, bfl, lR, lK, brinkman_inverse_permeability);
745:       }
746: 
747:     } // g: loop
748: 
749:     eq.linear_algebra->assemble(com_mod, eNoN, ptr, lK, lR);
750:     if (com_mod.risFlag) {
751:       if (!std::all_of(com_mod.ris.clsFlg.begin(), com_mod.ris.clsFlg.end(), [](bool v) { return v; })) {
752:         ris::doassem_ris(com_mod, eNoN, ptr, lK, lR);
753:       }
754:     }

momentum.excerpt:
1768: void fluid_3d_m(ComMod& com_mod, const int vmsFlag, const int eNoNw, const int eNoNq, const double w,
1769:     const Array<double>& Kxi, const Vector<double>& Nw, const Vector<double>& Nq, const Array<double>& Nwx,
1770:     const Array<double>& Nqx, const Array<double>& Nwxx, const Array<double>& al, const Array<double>& yl,
1771:     const Array<double>& bfl, Array<double>& lR, Array3<double>& lK, double brinkman_inverse_permeability,
1772:     const double urisFactorTotal, const Vector<double>& urisValveVelTermTotal)
1773: {
1774:   #define n_debug_fluid_3d_m
1775:   #ifdef debug_fluid_3d_m
1776:   DebugMsg dmsg(__func__, com_mod.cm.idcm());
1777:   dmsg.banner();
1778:   dmsg << "vmsFlag: " << vmsFlag;
1779:   dmsg << "eNoNw: " << eNoNw;
1780:   dmsg << "eNoNq: " << eNoNq;
1781:   dmsg << "w: " << w;
1782:   double start_time = utils::cput();
1783:   #endif
1784: 
1785:   // Maximum size of arrays sized by (3,eNoNw) -> (3,MAX_SIZE).
1786:   const int MAX_SIZE = 27;
1787: 
1788:   using namespace consts;
1789: 
1790:   int cEq = com_mod.cEq;
1791:   auto& eq = com_mod.eq[cEq];
1792:   int cDmn = com_mod.cDmn;
1793:   auto& dmn = eq.dmn[cDmn];
1794:   const double dt = com_mod.dt;
1795: 
1796:   double ctM  = 1.0;
1797:   double ctC  = 36.0;
1798: 
1799:   double rho = dmn.prop[PhysicalPropertyType::fluid_density];
1800:   std::array<double,3> f;
1801:   f[0] = dmn.prop[PhysicalPropertyType::f_x];
1802:   f[1] = dmn.prop[PhysicalPropertyType::f_y];
1803:   f[2] = dmn.prop[PhysicalPropertyType::f_z];
1804: 
1805:   double T1 = eq.af * eq.gam * dt;
1806:   double amd = eq.am / T1;
1807:   double wl = w*T1;
1808:   double wr = w*rho;
1809: 
1810:   #ifdef debug_fluid_3d_m
1811:   dmsg << "rho: " << rho;
1812:   dmsg << "T1: " << T1;
1813:   dmsg << "wl: " << wl;
1814:   dmsg << "wr: " << wr;
1815:   #endif
1816: 
1817:   // Note that indices are not selected based on the equation because
1818:   // fluid equation always come first
1819:   // Velocity and its gradients, inertia (acceleration & body force)
1820:   //
1821:   std::array<double,3> ud{-f[0], -f[1], -f[2]};
1822:   //ud  = -f
1823:   double u[3] = {};
1824:   double ux[3][3] = {};
1825:   double uxx[3][3][3] = {};
1826: 
1827:   for (int a = 0; a < eNoNw; a++) {
1828:     ud[0] = ud[0] + Nw(a)*(al(0,a)-bfl(0,a));
1829:     ud[1] = ud[1] + Nw(a)*(al(1,a)-bfl(1,a));
1830:     ud[2] = ud[2] + Nw(a)*(al(2,a)-bfl(2,a));
1831: 
1832:     u[0] = u[0] + Nw(a)*yl(0,a);
1833:     u[1] = u[1] + Nw(a)*yl(1,a);
1834:     u[2] = u[2] + Nw(a)*yl(2,a);
1835:     
1836:     ux[0][0] += Nwx(0,a)*yl(0,a);
1837:     ux[1][0] += Nwx(1,a)*yl(0,a);
1838:     ux[2][0] += Nwx(2,a)*yl(0,a);
1839:     ux[0][1] += Nwx(0,a)*yl(1,a);
1840:     ux[1][1] += Nwx(1,a)*yl(1,a);
1841:     ux[2][1] += Nwx(2,a)*yl(1,a);
1842:     ux[0][2] += Nwx(0,a)*yl(2,a);
1843:     ux[1][2] += Nwx(1,a)*yl(2,a);
1844:     ux[2][2] += Nwx(2,a)*yl(2,a);
1845: 
1846:     uxx[0][0][0] += Nwxx(0,a)*yl(0,a);
1847:     uxx[1][0][1] += Nwxx(1,a)*yl(0,a);
1848:     uxx[2][0][2] += Nwxx(2,a)*yl(0,a);
1849:     uxx[1][0][0] += Nwxx(3,a)*yl(0,a);
1850:     uxx[2][0][1] += Nwxx(4,a)*yl(0,a);
1851:     uxx[0][0][2] += Nwxx(5,a)*yl(0,a);
1852: 
1853:     uxx[0][1][0] += Nwxx(0,a)*yl(1,a);
1854:     uxx[1][1][1] += Nwxx(1,a)*yl(1,a);
1855:     uxx[2][1][2] += Nwxx(2,a)*yl(1,a);
1856:     uxx[1][1][0] += Nwxx(3,a)*yl(1,a);
1857:     uxx[2][1][1] += Nwxx(4,a)*yl(1,a);
1858:     uxx[0][1][2] += Nwxx(5,a)*yl(1,a);
1859: 
1860:     uxx[0][2][0] += Nwxx(0,a)*yl(2,a);
1861:     uxx[1][2][1] += Nwxx(1,a)*yl(2,a);
1862:     uxx[2][2][2] += Nwxx(2,a)*yl(2,a);
1863:     uxx[1][2][0] += Nwxx(3,a)*yl(2,a);
1864:     uxx[2][2][1] += Nwxx(4,a)*yl(2,a);
1865:     uxx[0][2][2] += Nwxx(5,a)*yl(2,a);
1866:   }
1867: 
1868:   double divU = ux[0][0] + ux[1][1] + ux[2][2];
1869:   #ifdef debug_fluid_3d_m
1870:   dmsg << "divU: " << divU;
1871:   #endif
1872: 
1873:   uxx[0][0][1] = uxx[1][0][0];
1874:   uxx[1][0][2] = uxx[2][0][1];
1875:   uxx[2][0][0] = uxx[0][0][2];
1876: 
1877:   uxx[0][1][1] = uxx[1][1][0];
1878:   uxx[1][1][2] = uxx[2][1][1];
1879:   uxx[2][1][0] = uxx[0][1][2];
1880: 
1881:   uxx[0][2][1] = uxx[1][2][0];
1882:   uxx[1][2][2] = uxx[2][2][1];
1883:   uxx[2][2][0] = uxx[0][2][2];
1884: 
1885:   std::array<double,3> d2u2{0.0};
1886:   d2u2[0] = uxx[0][0][0] + uxx[1][0][1] + uxx[2][0][2];
1887:   d2u2[1] = uxx[0][1][0] + uxx[1][1][1] + uxx[2][1][2];
1888:   d2u2[2] = uxx[0][2][0] + uxx[1][2][1] + uxx[2][2][2];
1889: 
1890:   // Pressure and its gradient
1891:   //
1892:   double p = 0.0;
1893:   double px[3] = {};
1894: 
1895:   for (int a = 0; a < eNoNq; a++) {
1896:     p  = p + Nq(a)*yl(3,a);
1897:     px[0] = px[0] + Nqx(0,a)*yl(3,a);
1898:     px[1] = px[1] + Nqx(1,a)*yl(3,a);
1899:     px[2] = px[2] + Nqx(2,a)*yl(3,a);
1900:   }
1901:   #ifdef debug_fluid_3d_m
1902:   dmsg << "u: " << u[0] << " " << u[1] << " " << u[2];
1903:   dmsg << "p: " << p;
1904:   dmsg << "px: " << px[0] << " " << px[1] << " " << px[2];
1905:   #endif
1906: 
1907:   // Update convection velocity relative to mesh velocity
1908:   //
1909:   if (com_mod.mvMsh) {
1910:     for (int a = 0; a < eNoNw; a++) {
1911:       u[0] = u[0] - Nw(a)*yl(4,a);
1912:       u[1] = u[1] - Nw(a)*yl(5,a);
1913:       u[2] = u[2] - Nw(a)*yl(6,a);
1914:     }
1915:   }
1916: 
1917:   // Strain rate tensor 2*e_ij := (u_i,j + u_j,i)
1918:   //
1919:   double es[3][3] = {};
1920:   es[0][0] = ux[0][0] + ux[0][0];
1921:   es[1][1] = ux[1][1] + ux[1][1];
1922:   es[2][2] = ux[2][2] + ux[2][2];
1923:   es[1][0] = ux[1][0] + ux[0][1];
1924:   es[2][1] = ux[2][1] + ux[1][2];
1925:   es[0][2] = ux[0][2] + ux[2][0];
1926:   es[0][1] = es[1][0];
1927:   es[1][2] = es[2][1];
1928:   es[2][0] = es[0][2];
1929: 
1930:   double esNx[3][MAX_SIZE];
1931: 
1932:   for (int a = 0; a < eNoNw; a++) {
1933:     esNx[0][a] = es[0][0]*Nwx(0,a) + es[1][0]*Nwx(1,a) + es[2][0]*Nwx(2,a);
1934:     esNx[1][a] = es[0][1]*Nwx(0,a) + es[1][1]*Nwx(1,a) + es[2][1]*Nwx(2,a);
1935:     esNx[2][a] = es[0][2]*Nwx(0,a) + es[1][2]*Nwx(1,a) + es[2][2]*Nwx(2,a);
1936:   }
1937: 
1938:   double es_x[3][3][3];
1939: 
1940:   for (int k = 0; k < 3; k++) { 
1941:      es_x[0][0][k] = uxx[0][0][k] + uxx[0][0][k];
1942:      es_x[1][1][k] = uxx[1][1][k] + uxx[1][1][k];
1943:      es_x[2][2][k] = uxx[2][2][k] + uxx[2][2][k];
1944:      es_x[1][0][k] = uxx[1][0][k] + uxx[0][1][k];
1945:      es_x[2][1][k] = uxx[2][1][k] + uxx[1][2][k];
1946:      es_x[0][2][k] = uxx[0][2][k] + uxx[2][0][k];
1947: 
1948:      es_x[0][1][k] = es_x[1][0][k];
1949:      es_x[1][2][k] = es_x[2][1][k];
1950:      es_x[2][0][k] = es_x[0][2][k];
1951:   }
1952: 
1953:   std::array<double,3> mu_x{0.0};
1954: 
1955:   mu_x[0] = (es_x[0][0][0]*es[0][0] + es_x[1][1][0]*es[1][1]
1956:           +  es_x[2][2][0]*es[2][2])*0.5
1957:           +  es_x[1][0][0]*es[1][0] + es_x[2][1][0]*es[2][1]
1958:           +  es_x[0][2][0]*es[0][2];
1959: 
1960:   mu_x[1] = (es_x[0][0][1]*es[0][0] + es_x[1][1][1]*es[1][1]
1961:           +  es_x[2][2][1]*es[2][2])*0.5
1962:           +  es_x[1][0][1]*es[1][0] + es_x[2][1][1]*es[2][1]
1963:           +  es_x[0][2][1]*es[0][2];
1964: 
1965:   mu_x[2] = (es_x[0][0][2]*es[0][0] + es_x[1][1][2]*es[1][1]
1966:           +  es_x[2][2][2]*es[2][2])*0.5
1967:           +  es_x[1][0][2]*es[1][0] + es_x[2][1][2]*es[2][1]
1968:           +  es_x[0][2][2]*es[0][2];
1969: 
1970:   #ifdef debug_fluid_3d_m
1971:   dmsg << "mu_x: " << mu_x[0] << " " << mu_x[1] << " " << mu_x[2];
1972:   #endif
1973: 
1974:   // Shear-rate := (2*e_ij*e_ij)^.5
1975:   //
1976:   //dmsg << "Compute shear rate ... ";
1977:   double gam = es[0][0]*es[0][0] + es[1][0]*es[1][0] + es[2][0]*es[2][0]
1978:              + es[0][1]*es[0][1] + es[1][1]*es[1][1] + es[2][1]*es[2][1]
1979:              + es[0][2]*es[0][2] + es[1][2]*es[1][2] + es[2][2]*es[2][2];
1980:   gam = sqrt(0.5*gam);
1981:   #ifdef debug_fluid_3d_m
1982:   dmsg << "gam: " << gam;
1983:   #endif
1984: 
1985:   // Compute viscosity based on shear-rate and chosen viscosity model
1986:   // The returned mu_g := (d\mu / d\gamma)
1987:   //
1988:   double mu, mu_s, mu_g;
1989:   fluid::get_viscosity(com_mod, dmn, gam, mu, mu_s, mu_g);
1990: 
1991:   if (utils::is_zero(gam)) {
1992:      mu_g = 0.0;
1993:   } else {
1994:      mu_g = mu_g / gam;
1995:   }
1996:   std::transform(mu_x.begin(), mu_x.end(), mu_x.begin(), [mu_g](double &v){return mu_g*v;});
1997:   //mu_x(:) = mu_g * mu_x(:)
1998: 
1999:   // Stabilization parameters
2000:   //
2001:   double kT = 4.0 * pow(ctM/dt,2.0);
2002:   
2003:   // If we consider the NSB model, we need to add an extra term inside the computation for the stab parameter 
2004:   kT = kT + pow(brinkman_inverse_permeability*mu/rho, 2.0);
2005: 
2006:   // In case of unfitted RIS, compute the delta function at the quad point,
2007:   // add the additional value to the stabilization param 
2008:   kT = kT + pow(urisFactorTotal, 2.0);
2009: 
2010:   double kU = u[0]*u[0]*Kxi(0,0) + u[1]*u[0]*Kxi(1,0) + u[2]*u[0]*Kxi(2,0)
2011:             + u[0]*u[1]*Kxi(0,1) + u[1]*u[1]*Kxi(1,1) + u[2]*u[1]*Kxi(2,1)
2012:             + u[0]*u[2]*Kxi(0,2) + u[1]*u[2]*Kxi(1,2) + u[2]*u[2]*Kxi(2,2);
2013: 
2014:   double kS = Kxi(0,0)*Kxi(0,0) + Kxi(1,0)*Kxi(1,0) + Kxi(2,0)*Kxi(2,0)
2015:             + Kxi(0,1)*Kxi(0,1) + Kxi(1,1)*Kxi(1,1) + Kxi(2,1)*Kxi(2,1)
2016:             + Kxi(0,2)*Kxi(0,2) + Kxi(1,2)*Kxi(1,2) + Kxi(2,2)*Kxi(2,2);
2017:   kS = ctC * kS * pow(mu/rho,2.0);
2018:   double tauM = 1.0 / (rho * sqrt( kT + kU + kS ));
2019: 
2020:   #ifdef debug_fluid_3d_m
2021:   dmsg << "kT: " << kT;
2022:   dmsg << "kU: " << kU;
2023:   dmsg << "kS: " << kS;
2024:   dmsg << "tauM: " << tauM;
2025:   #endif
2026: 
2027:   double rV[3] = {};
2028:   rV[0] = ud[0] + u[0]*ux[0][0] + u[1]*ux[1][0] + u[2]*ux[2][0];
2029:   rV[1] = ud[1] + u[0]*ux[0][1] + u[1]*ux[1][1] + u[2]*ux[2][1];
