2051:   double ua[3] = {};
2052: 
2053:   if (vmsFlag) {
2054:     tauC = 1.0 / (tauM * (Kxi(0,0) + Kxi(1,1) + Kxi(2,2)));
2055:     tauB = up[0]*up[0]*Kxi(0,0) + up[1]*up[0]*Kxi(1,0)
