1443: void fluid_3d_c(ComMod& com_mod, const int vmsFlag, const int eNoNw, const int eNoNq, const double w, 
1444:     const Array<double>& Kxi, const Vector<double>& Nw, const Vector<double>& Nq, const Array<double>& Nwx, 
1445:     const Array<double>& Nqx, const Array<double>& Nwxx, const Array<double>& al, const Array<double>& yl, 
1446:     const Array<double>& bfl, Array<double>& lR, Array3<double>& lK, double brinkman_inverse_permeability,
1447:     const double urisFactorTotal, const Vector<double>& urisValveVelTermTotal)
1448: {
1449:   #define n_debug_fluid3d_c
1450:   #ifdef debug_fluid3d_c
1451:   DebugMsg dmsg(__func__, com_mod.cm.idcm());
