1454:   dmsg << "eNoNw: " << eNoNw;
1455:   dmsg << "eNoNq: " << eNoNq;
1456:   double start_time = utils::cput();
1457:   #endif
1458:   
1459:   // Maximum size of arrays sized by (3,eNoNw) -> (3,MAX_SIZE).
1460:   const int MAX_SIZE = 27;
1461: 
1462:   using namespace consts;
1463: 
1464:   int cEq = com_mod.cEq;
1465:   auto& eq = com_mod.eq[cEq];
1466:   int cDmn = com_mod.cDmn;
1467:   auto& dmn = eq.dmn[cDmn];
1468:   const double dt = com_mod.dt;
1469: 
1470:   const double ctM  = 1.0;
1471:   const double ctC  = 36.0;
1472: 
1473:   double rho = dmn.prop[PhysicalPropertyType::fluid_density];
1474:   double f[3];
1475:   f[0] = dmn.prop[PhysicalPropertyType::f_x];
1476:   f[1] = dmn.prop[PhysicalPropertyType::f_y];
1477:   f[2] = dmn.prop[PhysicalPropertyType::f_z];
1478: 
1479:   double T1 = eq.af * eq.gam * dt;
1480:   double amd = eq.am / T1;
1481:   double wl = w*T1;
1482:   double wr = w*rho;
1483: 
1484:   // Note that indices are not selected based on the equation because
1485:   // fluid equation always come first
1486:   // Velocity and its gradients, inertia (acceleration & body force)
1487:   //
1488:   double ud[3] = {-f[0], -f[1], -f[2]};
1489:   double u[3] = {};
1490:   double ux[3][3] = {};
1491:   double uxx[3][3][3] = {};
1492: 
1493:   for (int a = 0; a < eNoNw; a++) {
1494:     ud[0] = ud[0] + Nw(a)*(al(0,a)-bfl(0,a));
1495:     ud[1] = ud[1] + Nw(a)*(al(1,a)-bfl(1,a));
1496:     ud[2] = ud[2] + Nw(a)*(al(2,a)-bfl(2,a));
1497: 
1498:     u[0] = u[0] + Nw(a)*yl(0,a);
1499:     u[1] = u[1] + Nw(a)*yl(1,a);
1500:     u[2] = u[2] + Nw(a)*yl(2,a);
1501: 
1502:     ux[0][0] = ux[0][0] + Nwx(0,a)*yl(0,a);
1503:     ux[1][0] = ux[1][0] + Nwx(1,a)*yl(0,a);
1504:     ux[2][0] = ux[2][0] + Nwx(2,a)*yl(0,a);
1505:     ux[0][1] = ux[0][1] + Nwx(0,a)*yl(1,a);
1506:     ux[1][1] = ux[1][1] + Nwx(1,a)*yl(1,a);
1507:     ux[2][1] = ux[2][1] + Nwx(2,a)*yl(1,a);
1508:     ux[0][2] = ux[0][2] + Nwx(0,a)*yl(2,a);
1509:     ux[1][2] = ux[1][2] + Nwx(1,a)*yl(2,a);
1510:     ux[2][2] = ux[2][2] + Nwx(2,a)*yl(2,a);
1511: 
1512:     uxx[0][0][0] += Nwxx(0,a)*yl(0,a);
1513:     uxx[1][0][1] += Nwxx(1,a)*yl(0,a);
1514:     uxx[2][0][2] += Nwxx(2,a)*yl(0,a);
1515:     uxx[1][0][0] += Nwxx(3,a)*yl(0,a);
1516:     uxx[2][0][1] += Nwxx(4,a)*yl(0,a);
1517:     uxx[0][0][2] += Nwxx(5,a)*yl(0,a);
1518: 
1519:     uxx[0][1][0] += Nwxx(0,a)*yl(1,a);
1520:     uxx[1][1][1] += Nwxx(1,a)*yl(1,a);
1521:     uxx[2][1][2] += Nwxx(2,a)*yl(1,a);
1522:     uxx[1][1][0] += Nwxx(3,a)*yl(1,a);
1523:     uxx[2][1][1] += Nwxx(4,a)*yl(1,a);
1524:     uxx[0][1][2] += Nwxx(5,a)*yl(1,a);
1525: 
1526:     uxx[0][2][0] += Nwxx(0,a)*yl(2,a);
1527:     uxx[1][2][1] += Nwxx(1,a)*yl(2,a);
1528:     uxx[2][2][2] += Nwxx(2,a)*yl(2,a);
1529:     uxx[1][2][0] += Nwxx(3,a)*yl(2,a);
1530:     uxx[2][2][1] += Nwxx(4,a)*yl(2,a);
1531:     uxx[0][2][2] += Nwxx(5,a)*yl(2,a);
1532:   }
1533: 
1534:   double divU = ux[0][0] + ux[1][1] + ux[2][2];
1535: 
1536:   uxx[0][0][1] = uxx[1][0][0];
1537:   uxx[1][0][2] = uxx[2][0][1];
1538:   uxx[2][0][0] = uxx[0][0][2];
1539: 
1540:   uxx[0][1][1] = uxx[1][1][0];
1541:   uxx[1][1][2] = uxx[2][1][1];
1542:   uxx[2][1][0] = uxx[0][1][2];
1543: 
1544:   uxx[0][2][1] = uxx[1][2][0];
1545:   uxx[1][2][2] = uxx[2][2][1];
1546:   uxx[2][2][0] = uxx[0][2][2];
1547: 
1548:   double d2u2[3] = {};
1549:   d2u2[0] = uxx[0][0][0] + uxx[1][0][1] + uxx[2][0][2];
1550:   d2u2[1] = uxx[0][1][0] + uxx[1][1][1] + uxx[2][1][2];
1551:   d2u2[2] = uxx[0][2][0] + uxx[1][2][1] + uxx[2][2][2];
1552: 
1553:   // Pressure and its gradient
1554:   //
1555:   double px[3] = {};
1556: 
1557:   for (int a = 0; a < eNoNq; a++) {
1558:     px[0] = px[0] + Nqx(0,a)*yl(3,a);
1559:     px[1] = px[1] + Nqx(1,a)*yl(3,a);
1560:     px[2] = px[2] + Nqx(2,a)*yl(3,a);
1561:   }
1562: 
1563:   // Update convection velocity relative to mesh velocity
1564:   //
1565:   if (com_mod.mvMsh) {
1566:     for (int a = 0; a < eNoNw; a++) {
1567:       u[0] = u[0] - Nw(a)*yl(4,a);
1568:       u[1] = u[1] - Nw(a)*yl(5,a);
1569:       u[2] = u[2] - Nw(a)*yl(6,a);
1570:     }
1571:   }
1572: 
1573:   // Strain rate tensor 2*e_ij := (u_i,j + u_j,i)
1574:   //
1575:   double es[3][3] = {};
1576:   es[0][0] = ux[0][0] + ux[0][0];
1577:   es[1][1] = ux[1][1] + ux[1][1];
1578:   es[2][2] = ux[2][2] + ux[2][2];
1579:   es[1][0] = ux[1][0] + ux[0][1];
1580:   es[2][1] = ux[2][1] + ux[1][2];
1581:   es[0][2] = ux[0][2] + ux[2][0];
1582:   es[0][1] = es[1][0];
1583:   es[1][2] = es[2][1];
1584:   es[2][0] = es[0][2];
1585: 
1586:   double esNx[3][MAX_SIZE];
1587: 
1588:   for (int a = 0; a < eNoNw; a++) {
1589:     esNx[0][a] = es[0][0]*Nwx(0,a) + es[1][0]*Nwx(1,a) + es[2][0]*Nwx(2,a);
1590:     esNx[1][a] = es[0][1]*Nwx(0,a) + es[1][1]*Nwx(1,a) + es[2][1]*Nwx(2,a);
1591:     esNx[2][a] = es[0][2]*Nwx(0,a) + es[1][2]*Nwx(1,a) + es[2][2]*Nwx(2,a);
1592:   }
1593: 
1594:   double es_x[3][3][3] = {};
1595: 
1596:   for (int k = 0; k < 3; k++) { 
1597:      es_x[0][0][k] = uxx[0][0][k] + uxx[0][0][k];
1598:      es_x[1][1][k] = uxx[1][1][k] + uxx[1][1][k];
1599:      es_x[2][2][k] = uxx[2][2][k] + uxx[2][2][k];
1600:      es_x[1][0][k] = uxx[1][0][k] + uxx[0][1][k];
1601:      es_x[2][1][k] = uxx[2][1][k] + uxx[1][2][k];
1602:      es_x[0][2][k] = uxx[0][2][k] + uxx[2][0][k];
1603: 
1604:      es_x[0][1][k] = es_x[1][0][k];
1605:      es_x[1][2][k] = es_x[2][1][k];
1606:      es_x[2][0][k] = es_x[0][2][k];
1607:   }
1608: 
1609:   double mu_x[3];
1610: 
1611:   mu_x[0] = (es_x[0][0][0]*es[0][0] + es_x[1][1][0]*es[1][1]
1612:           +  es_x[2][2][0]*es[2][2])*0.5
1613:           +  es_x[1][0][0]*es[1][0] + es_x[2][1][0]*es[2][1]
1614:           +  es_x[0][2][0]*es[0][2];
1615: 
1616:   mu_x[1] = (es_x[0][0][1]*es[0][0] + es_x[1][1][1]*es[1][1]
1617:           +  es_x[2][2][1]*es[2][2])*0.5
1618:           +  es_x[1][0][1]*es[1][0] + es_x[2][1][1]*es[2][1]
1619:           +  es_x[0][2][1]*es[0][2];
1620: 
1621:   mu_x[2] = (es_x[0][0][2]*es[0][0] + es_x[1][1][2]*es[1][1]
1622:           +  es_x[2][2][2]*es[2][2])*0.5
1623:           +  es_x[1][0][2]*es[1][0] + es_x[2][1][2]*es[2][1]
1624:           +  es_x[0][2][2]*es[0][2];
1625: 
1626:   // Shear-rate := (2*e_ij*e_ij)^.5
1627:   double gam = es[0][0]*es[0][0] + es[1][0]*es[1][0] + es[2][0]*es[2][0]
1628:              + es[0][1]*es[0][1] + es[1][1]*es[1][1] + es[2][1]*es[2][1]
1629:              + es[0][2]*es[0][2] + es[1][2]*es[1][2] + es[2][2]*es[2][2];
1630:   gam = sqrt(0.5*gam);
1631: 
1632:   // Compute viscosity based on shear-rate and chosen viscosity model
1633:   // The returned mu_g := (d\mu / d\gamma)
1634:   double mu, mu_s, mu_g;
1635:   get_viscosity(com_mod, dmn, gam, mu, mu_s, mu_g);
1636: 
1637:   if (utils::is_zero(gam)) {
1638:      mu_g = 0.0;
1639:   } else {
1640:      mu_g = mu_g / gam;
1641:   }
1642: 
1643:   for (int i = 0; i < 3; i++) {
1644:     mu_x[i] = mu_g * mu_x[i];
1645:   }
1646: 
1647:   // Stabilization parameters
1648:   //
1649:   double up[3] = {};
1650:   double updu[3][3][MAX_SIZE] = {};
1651:   double tauM = 0.0;
1652: 
1653:   if (vmsFlag) {
1654:     // Stabilization parameters
1655:     double kT = 4.0 * pow(ctM/dt,2.0);
1656:     
1657:     // If we consider the NSB model, we need to add an extra term inside the computation for the stab parameter 
1658:     kT = kT + pow(brinkman_inverse_permeability*mu/rho, 2.0);
1659:     
1660:     // In case of unfitted RIS, compute the delta function at the quad point,
1661:     // add the additional value to the stabilization param 
1662:     kT = kT + pow(urisFactorTotal, 2.0);
1663: 
1664:     double kU = u[0]*u[0]*Kxi(0,0) + u[1]*u[0]*Kxi(1,0) + u[2]*u[0]*Kxi(2,0)
1665:               + u[0]*u[1]*Kxi(0,1) + u[1]*u[1]*Kxi(1,1) + u[2]*u[1]*Kxi(2,1)
1666:               + u[0]*u[2]*Kxi(0,2) + u[1]*u[2]*Kxi(1,2) + u[2]*u[2]*Kxi(2,2);
1667: 
1668:     double kS = Kxi(0,0)*Kxi(0,0) + Kxi(1,0)*Kxi(1,0) + Kxi(2,0)*Kxi(2,0)
1669:               + Kxi(0,1)*Kxi(0,1) + Kxi(1,1)*Kxi(1,1) + Kxi(2,1)*Kxi(2,1)
1670:               + Kxi(0,2)*Kxi(0,2) + Kxi(1,2)*Kxi(1,2) + Kxi(2,2)*Kxi(2,2);
1671: 
1672:     kS = ctC * kS * pow(mu/rho,2.0);
1673:     tauM = 1.0 / (rho * sqrt( kT + kU + kS ));
1674: 
1675:     double rV[3];
1676:     rV[0] = ud[0] + u[0]*ux[0][0] + u[1]*ux[1][0] + u[2]*ux[2][0];
1677:     rV[1] = ud[1] + u[0]*ux[0][1] + u[1]*ux[1][1] + u[2]*ux[2][1];
1678:     rV[2] = ud[2] + u[0]*ux[0][2] + u[1]*ux[1][2] + u[2]*ux[2][2];
1679: 
1680:     double rS[3];
1681:     rS[0] = mu_x[0]*es[0][0] + mu_x[1]*es[1][0] + mu_x[2]*es[2][0] + mu*d2u2[0];
1682:     rS[1] = mu_x[0]*es[0][1] + mu_x[1]*es[1][1] + mu_x[2]*es[2][1] + mu*d2u2[1];
1683:     rS[2] = mu_x[0]*es[0][2] + mu_x[1]*es[1][2] + mu_x[2]*es[2][2] + mu*d2u2[2];
1684: 
1685:     // up[0] = -tauM*(rho*rV[0] + px[0] - rS[0] + mu*brinkman_inverse_permeability*u[0]);
1686:     // up[1] = -tauM*(rho*rV[1] + px[1] - rS[1] + mu*brinkman_inverse_permeability*u[1]);
1687:     // up[2] = -tauM*(rho*rV[2] + px[2] - rS[2] + mu*brinkman_inverse_permeability*u[2]);
1688: 
1689:     up[0] = -tauM*(rho*rV[0] + px[0] - rS[0] + mu*brinkman_inverse_permeability*u[0]
1690:                    + urisFactorTotal*u[0] - urisValveVelTermTotal[0]);
1691:     up[1] = -tauM*(rho*rV[1] + px[1] - rS[1] + mu*brinkman_inverse_permeability*u[1]
1692:                    + urisFactorTotal*u[1] - urisValveVelTermTotal[1]);
1693:     up[2] = -tauM*(rho*rV[2] + px[2] - rS[2] + mu*brinkman_inverse_permeability*u[2]
1694:                    + urisFactorTotal*u[2] - urisValveVelTermTotal[2]);
1695: 
1696:     for (int a = 0; a < eNoNw; a++) {
1697:       double uNx = u[0]*Nwx(0,a) + u[1]*Nwx(1,a) + u[2]*Nwx(2,a);
1698:       // T1 = -rho*uNx + mu*(Nwxx(0,a) + Nwxx(1,a) + Nwxx(2,a)) + mu_x[0]*Nwx(0,a) + mu_x[1]*Nwx(1,a) + mu_x[2]*Nwx(2,a) - mu*brinkman_inverse_permeability*Nw(a);
1699: 
1700:       T1 = -rho*uNx + mu*(Nwxx(0,a) + Nwxx(1,a) + Nwxx(2,a)) 
1701:            + mu_x[0]*Nwx(0,a) + mu_x[1]*Nwx(1,a) + mu_x[2]*Nwx(2,a) 
1702:            - mu*brinkman_inverse_permeability*Nw(a)
1703:            - urisFactorTotal*Nw(a);
1704: 
1705:       updu[0][0][a] = mu_x[0]*Nwx(0,a) + d2u2[0]*mu_g*esNx[0][a] + T1;
1706:       updu[1][0][a] = mu_x[1]*Nwx(0,a) + d2u2[1]*mu_g*esNx[0][a];
1707:       updu[2][0][a] = mu_x[2]*Nwx(0,a) + d2u2[2]*mu_g*esNx[0][a];
1708:   
1709:       updu[0][1][a] = mu_x[0]*Nwx(1,a) + d2u2[0]*mu_g*esNx[1][a];
1710:       updu[1][1][a] = mu_x[1]*Nwx(1,a) + d2u2[1]*mu_g*esNx[1][a] + T1;
1711:       updu[2][1][a] = mu_x[2]*Nwx(1,a) + d2u2[2]*mu_g*esNx[1][a];
1712:   
1713:       updu[0][2][a] = mu_x[0]*Nwx(2,a) + d2u2[0]*mu_g*esNx[2][a];
1714:       updu[1][2][a] = mu_x[1]*Nwx(2,a) + d2u2[1]*mu_g*esNx[2][a];
1715:       updu[2][2][a] = mu_x[2]*Nwx(2,a) + d2u2[2]*mu_g*esNx[2][a] + T1;
1716:     }
1717: 
1718:   } else {
1719:     tauM = 0.0;
1720:     std::memset(up, 0, sizeof up);
1721:     std::memset(updu, 0, sizeof updu);
1722:   }
1723: 
1724:   //  Local residual
1725:   //
1726:   for (int a = 0; a < eNoNq; a++) {
