1738:       double T2 = Nqx(0,a)*(updu[0][0][b] - T1) + Nqx(1,a)*updu[0][1][b] + Nqx(2,a)*updu[0][2][b];
1739:       lK(12,a,b) = lK(12,a,b) + wl*(Nq(a)*Nwx(0,b) - tauM*T2);
1740: 
1741:       // dRc_a/dU_b2
1742:       T2 = Nqx(0,a)*updu[1][0][b] + Nqx(1,a)*(updu[1][1][b] - T1) + Nqx(2,a)*updu[1][2][b];
1743:       lK(13,a,b) = lK(13,a,b) + wl*(Nq(a)*Nwx(1,b) - tauM*T2);
1744: 
1745:       // dRc_a/dU_b3
1746:       T2 = Nqx(0,a)*updu[2][0][b] + Nqx(1,a)*updu[2][1][b] + Nqx(2,a)*(updu[2][2][b] - T1);
1747:       lK(14,a,b) = lK(14,a,b) + wl*(Nq(a)*Nwx(2,b) - tauM*T2);
1748:     }
1749:   }
1750: 
1751:   if (vmsFlag) {
1752:     for (int b = 0; b < eNoNq; b++) {
1753:       for (int a = 0; a < eNoNq; a++) {
1754:         // dC/dP
1755:         double NxNx = Nqx(0,a)*Nqx(0,b) + Nqx(1,a)*Nqx(1,b) + Nqx(2,a)*Nqx(2,b);
1756:         lK(15,a,b) = lK(15,a,b) + wl*tauM*NxNx;
1757:       }
1758:     }
1759:   }
1760: }
