405: /*
406:     Creating PETSc lhs data structure with svFSI info.
407: */
408: PetscErrorCode petsc_create_lhs(const PetscInt nNo, const PetscInt mynNo, const PetscInt nnz, \
409:                                 const PetscInt *svFSI_ltg, const PetscInt *svFSI_map, \
410:                                 const PetscInt *svFSI_rowPtr, const PetscInt *svFSI_colPtr)
411: {   
412:     PetscInt  i, j ;
413:     PetscErrorCode ierr;
414:     PetscInt *local2global, *local2local; /* local copy of svFSI ltg and map */
415:     PetscInt *local_ltg;                  /* local to global mapping of all vertices on current proc.*/
416:     PetscInt *owned_ltg;                  /* local to global mapping of owned vertices */
417:     PetscInt *ghost_ltg;                  /* local to global mapping of ghost vertices */
418:     PetscInt  rstart;                     /* starting index of PETSc ordering for a processor */
419:     AO        ao;                         /* Application Ordering object */
420:     PetscInt *pordering;                  /* PETSc ordering */
421:     PetscInt  ghostnNo;                   /* number of ghost vertices */
422: 
423:     PetscFunctionBeginUser;
424: 
425:     /* In cases with remeshing, lhs needs to be regenerated. */
426:     if (plhs.created) {
427:         PetscPrintf(MPI_COMM_WORLD, "ERROR <PETSC_DESTROY_ALL>: \
428:                 lhs is already created.");
429:         ierr = PETSC_ERR_ARG_WRONGSTATE;
430:         PETSCABORT(MPI_COMM_WORLD, ierr);
431:     }
432: 
433:     plhs.nNo     = nNo;
434:     plhs.mynNo   = mynNo;
435:     plhs.created = PETSC_TRUE;
436: 
437:     /* Fortran index to C index (NOT apply for svMultiPhysics) */ 
438:     PetscCall(PetscMalloc2(nNo, &local2global, nNo, &local2local));
439:     for (i = 0; i < nNo; i++) {
440:         // local2global[i] = svFSI_ltg[i] - 1;
441:         // local2local[i]  = svFSI_map[i] - 1;
442:         local2global[i] = svFSI_ltg[i];
443:         local2local[i]  = svFSI_map[i];
444:     }
445: 
446:     /* Create local mapping, map[O2] = O1 */
447:     PetscCall(PetscMalloc1(nNo, &plhs.map));
448:     for (i = 0; i < nNo; i++) {
449:         plhs.map[local2local[i]] = i;
450:     }
451: 
452:     /* - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - 
453:         Create global-to-global mapping using AO:
454:         - Global order 1 is from svFSI (ltg, i.e. O1).
455:         - Global order 2 is for PETSc (PETSc ordering). It is:
456:             |---- Proc 0-------|   |----------- Proc 2 ------------|
457:             0 1 ...   mynNo(0)-1    mynNo(0) ... mynNo(0)+mynNo(1)-1
458:         
459:         - Note that global order 2 locally follows O2 ordering, i.e.
460:            lower rank vtx + current rank vtx 
461:         - Vertices from higher rank are ghost vertices.
462:      - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - */
463:     /* Remap svFSI ltg to svFSI lhs%map order (O2) */
464:     PetscCall(PetscMalloc2(mynNo, &owned_ltg, nNo, &local_ltg));
465:     for (i = 0; i < nNo; i++) {
466:         j = local2local[i];
467:         local_ltg[j] = local2global[i];
468:     }
469:     for (i = 0; i < mynNo; i++) owned_ltg[i] = local_ltg[i];
470:     ghostnNo = nNo - mynNo;
471:     PetscCall(PetscMalloc1(ghostnNo, &ghost_ltg));
472:     for (i = 0; i < ghostnNo; i++) ghost_ltg[i] = local_ltg[i+mynNo];
473: 
474:     /* Create AO object between svFSI ltg and PETSc ordering */
475:     PetscCallMPI(MPI_Scan(&mynNo, &rstart, 1, MPIU_INT, MPI_SUM, MPI_COMM_WORLD));
476:     rstart -= mynNo;
477:     PetscCall(PetscMalloc1(mynNo, &pordering));
478:     for (i = 0; i < mynNo; i++) pordering[i] = rstart + i;
479:     PetscCall(AOCreateBasic(MPI_COMM_WORLD, mynNo, owned_ltg, pordering, &ao));
480: 
481:     /* 
482:         Now map the vertex id in natural ordering to PETSc ordering.
483:         Before AOApplicationToPetsc:
484:             local_ltg[i] = natural id, i = 0,..., nNo-1
485:         After AOApplicationToPetsc:
486:             local_ltg[i] = PETSc id, i = 0,..., nNo-1
487:     */
488:     PetscCall(AOApplicationToPetsc(ao, nNo, local_ltg));
489:     PetscCall(AOApplicationToPetsc(ao, ghostnNo, ghost_ltg));
490:     PetscCall(AODestroy(&ao));
491: 
492:     PetscCall(PetscMalloc2(nNo, &plhs.ltg, ghostnNo, &plhs.ghostltg));
493:     for (i = 0; i < nNo; i++) plhs.ltg[i] = local_ltg[i];
494:     for (i = 0; i < ghostnNo; i++) plhs.ghostltg[i] = ghost_ltg[i];
495: 
496:     /* Adjacency info in PETSc lhs (i.e plhs.rowPtr and plhs.colPtr) is used to set values. */
497:     PetscCall(PetscMalloc2(2*nNo, &plhs.rowPtr, nnz, &plhs.colPtr));
498:     for (i=0; i < nNo; i++) {
499:         // plhs.rowPtr[i*2]   = svFSI_rowPtr[i*2] - 1; 
500:         plhs.rowPtr[i*2]   = svFSI_rowPtr[i*2];
501:         // plhs.rowPtr[i*2+1] = svFSI_rowPtr[i*2+1];
502:         plhs.rowPtr[i*2+1] = svFSI_rowPtr[i*2+1]+1;
503:     }
504:     for (i=0; i < nnz; i++) {
505:         // plhs.colPtr[i] = plhs.ltg[svFSI_colPtr[i] - 1];
506:         plhs.colPtr[i] = plhs.ltg[svFSI_colPtr[i]];
507:     }
508:     
509:     /* Deallocate memory */
510:     PetscCall(PetscFree2(owned_ltg, local_ltg));
511:     PetscCall(PetscFree2(local2global, local2local));
512:     PetscCall(PetscFree(ghost_ltg));
513:     PetscCall(PetscFree(pordering));
514: 
515:     PetscFunctionReturn(PETSC_SUCCESS);
516: }
